-- Manahil-e-Quran Academy / quran.pajee.org
-- Neon PostgreSQL bootstrap (pooled DATABASE_URL in app; run migration using Neon's SQL Editor).
-- Run once BEFORE deploying; safe to re-run. Never executed during a public request.
-- Compatible with the original project's table names and existing data.
BEGIN;

-- Core project tables and indexes, formerly created in src/lib/db.ts on every query.

create table if not exists leads (
    id text primary key,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    status text not null default 'new',
    notes text not null default '',
    name text not null,
    phone text not null default '',
    email text not null default '',
    country text not null default '',
    course text not null default '',
    student_for text not null default '',
    student_age text not null default '',
    teacher_pref text not null default '',
    class_type text not null default '',
    student_count text not null default '',
    preferred_time text not null default '',
    timezone text not null default '',
    message text not null default '',
    source_page text not null default '',
    landing_page text not null default '',
    referrer text not null default '',
    utm_source text not null default '',
    utm_medium text not null default '',
    utm_campaign text not null default '',
    utm_term text not null default '',
    utm_content text not null default '',
    gclid text not null default '',
    fbclid text not null default ''
  );

alter table leads add column if not exists class_type text not null default '';

alter table leads add column if not exists student_count text not null default '';

create index if not exists leads_created_at_idx on leads (created_at desc);

create table if not exists users (
    id text primary key,
    created_at timestamptz not null default now(),
    role text not null,
    status text not null default 'active',
    name text not null,
    email text not null unique,
    pass_hash text not null,
    phone text not null default '',
    country text not null default '',
    timezone text not null default '',
    gender text not null default '',
    lang text not null default 'en',
    account_kind text not null default '',
    preferred_time text not null default '',
    about text not null default '',
    teaches text not null default ''
  );

create table if not exists students (
    id text primary key,
    created_at timestamptz not null default now(),
    user_id text not null references users(id) on delete cascade,
    name text not null,
    birth_year integer,
    gender text not null default '',
    course text not null default '',
    class_kind text not null default 'one',
    teacher_pref text not null default '',
    level text not null default '',
    notes text not null default ''
  );

create index if not exists students_user_idx on students (user_id);

create table if not exists classes (
    id text primary key,
    created_at timestamptz not null default now(),
    name text not null,
    kind text not null default 'one',
    course text not null default '',
    teacher_id text references users(id) on delete set null,
    schedule text not null default '',
    meeting_url text not null default '',
    status text not null default 'active'
  );

create index if not exists classes_teacher_idx on classes (teacher_id);

create table if not exists enrollments (
    class_id text not null references classes(id) on delete cascade,
    student_id text not null references students(id) on delete cascade,
    created_at timestamptz not null default now(),
    primary key (class_id, student_id)
  );

create table if not exists lessons (
    id text primary key,
    created_at timestamptz not null default now(),
    class_id text not null references classes(id) on delete cascade,
    teacher_id text,
    held_on text not null,
    topic text not null default '',
    homework text not null default ''
  );

create index if not exists lessons_class_idx on lessons (class_id, held_on desc);

create table if not exists lesson_marks (
    lesson_id text not null references lessons(id) on delete cascade,
    student_id text not null references students(id) on delete cascade,
    attendance text not null default 'present',
    rating integer,
    note text not null default '',
    primary key (lesson_id, student_id)
  );

create index if not exists lesson_marks_student_idx on lesson_marks (student_id);

create table if not exists quizzes (
    id text primary key,
    created_at timestamptz not null default now(),
    created_by text references users(id) on delete set null,
    title text not null,
    course text not null default '',
    questions jsonb not null
  );

create table if not exists quiz_assignments (
    id text primary key,
    created_at timestamptz not null default now(),
    quiz_id text not null,
    class_id text references classes(id) on delete cascade,
    student_id text references students(id) on delete cascade,
    assigned_by text,
    due_on text not null default ''
  );

create table if not exists quiz_attempts (
    id text primary key,
    taken_at timestamptz not null default now(),
    quiz_id text not null,
    assignment_id text,
    student_id text not null references students(id) on delete cascade,
    score integer not null,
    total integer not null,
    answers jsonb not null
  );

create index if not exists quiz_attempts_student_idx on quiz_attempts (student_id);

create table if not exists assessments (
    id text primary key,
    created_at timestamptz not null default now(),
    student_id text not null references students(id) on delete cascade,
    teacher_id text,
    held_on text not null,
    title text not null,
    score numeric not null,
    max_score numeric not null,
    note text not null default ''
  );

create index if not exists assessments_student_idx on assessments (student_id);

alter table assessments add column if not exists class_id text;

create table if not exists invoices (
    id text primary key,
    number bigserial,
    created_at timestamptz not null default now(),
    user_id text not null references users(id) on delete cascade,
    title text not null,
    period text not null default '',
    amount numeric not null,
    currency text not null default 'USD',
    due_on text not null default '',
    status text not null default 'due',
    pay_url text not null default '',
    note text not null default '',
    claimed_at timestamptz,
    claim_method text not null default '',
    claim_ref text not null default '',
    paid_at timestamptz,
    paid_method text not null default '',
    paid_ref text not null default ''
  );

create index if not exists invoices_user_idx on invoices (user_id, created_at desc);

alter table users add column if not exists monthly_fee numeric;

alter table users add column if not exists fee_currency text not null default 'USD';

create table if not exists settings (
    key text primary key,
    value text not null default ''
  );

create table if not exists staff (
    id text primary key,
    created_at timestamptz not null default now(),
    name text not null,
    email text not null unique,
    password_hash text not null,
    role text not null default 'editor',
    status text not null default 'active',
    last_login timestamptz
  );

create table if not exists cms_posts (
    id text primary key,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    published_at timestamptz,
    status text not null default 'draft',
    kind text not null default 'article',
    parent_id text,
    slug text not null unique,
    title text not null,
    excerpt text not null default '',
    answer text not null default '',
    body text not null default '',
    faqs text not null default '[]',
    seo_title text not null default '',
    seo_description text not null default '',
    focus_keyword text not null default '',
    canonical text not null default '',
    noindex boolean not null default false,
    og_image text not null default '',
    schema_type text not null default 'BlogPosting',
    schema_json text not null default '',
    author text not null default '',
    updated_by text not null default ''
  );

create index if not exists cms_posts_status_idx on cms_posts (status, kind);

create table if not exists page_seo (
    path text not null,
    lang text not null default 'en',
    title text not null default '',
    description text not null default '',
    noindex boolean not null default false,
    schema_json text not null default '',
    updated_at timestamptz not null default now(),
    updated_by text not null default '',
    primary key (path, lang)
  );

create table if not exists attempts (
    key text not null,
    at timestamptz not null default now()
  );

create index if not exists attempts_key_idx on attempts (key, at desc);


-- Allow the same guide slug in English, Urdu and Arabic, preserving old English rows.
ALTER TABLE cms_posts ADD COLUMN IF NOT EXISTS lang text NOT NULL DEFAULT 'en';
ALTER TABLE cms_posts DROP CONSTRAINT IF EXISTS cms_posts_slug_key;
CREATE UNIQUE INDEX IF NOT EXISTS cms_posts_slug_lang_idx ON cms_posts (slug, lang);
CREATE INDEX IF NOT EXISTS cms_posts_lang_status_idx ON cms_posts (lang, status, published_at DESC);

-- Block-based/field-based content overrides are opt-in at the page renderer.
-- Paths are unprefixed: '/', '/pricing', '/courses/noorani-qaida-online', '/blog/...'.
-- 'en', 'ur', and 'ar' each have their own independent content and publication status.
CREATE TABLE IF NOT EXISTS cms_page_overrides (
  path text NOT NULL,
  lang text NOT NULL CHECK (lang IN ('en', 'ur', 'ar')),
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
  content jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by text NOT NULL DEFAULT '',
  PRIMARY KEY (path, lang)
);
CREATE INDEX IF NOT EXISTS cms_page_overrides_status_idx ON cms_page_overrides (status, lang);

-- Reference price list used when quoting monthly fees; storefront TS constants match.
-- Group monthly fees are PER LEARNER and flat for all advertised class frequencies.
CREATE TABLE IF NOT EXISTS pricing_rates (
  plan_id text NOT NULL,
  currency text NOT NULL CHECK (currency IN ('USD', 'GBP', 'CAD', 'AUD')),
  class_type text NOT NULL CHECK (class_type IN ('one', 'family', 'community')),
  classes_per_week integer NOT NULL CHECK (classes_per_week IN (2, 3, 5)),
  classes_per_month integer NOT NULL,
  monthly_amount numeric(10,2) NOT NULL CHECK (monthly_amount >= 0),
  per_learner boolean NOT NULL DEFAULT false,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (plan_id, currency)
);
CREATE TABLE IF NOT EXISTS pricing_policies (
  key text PRIMARY KEY,
  value text NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- 20% discount on only the second child's one-to-one monthly plan.
INSERT INTO pricing_policies (key, value) VALUES
  ('sibling_second_child_percent', '20'),
  ('sibling_discount_group_stackable', 'false')
ON CONFLICT (key) DO NOTHING;


