-- Blog guide seed happens here (not in cms.ts). The settings marker prevents
-- re-seeding user-edited/deleted guides when a migration is re-run.

INSERT INTO cms_posts
 (id, created_at, updated_at, published_at, status, kind, parent_id, slug, title, excerpt, answer, body, faqs, seo_title, seo_description, focus_keyword, schema_type, author, lang)
